'use client'
import type { ReactNode } from 'react'
import { AccordionContext } from '@/react/hooks/useAccordion'
import { useControllable } from '@/react/hooks/useControllable'
import { cn } from '@/react/lib/cn'

// shadcn's accordion in the brand: a stack of disclosures on black with neutral hairlines between the rows, a muted
// chevron that turns as a row opens, the row opening to its content's height over 320ms on the strong ease-out and
// closing in 160ms. One open at a time by default (a second press closes it); `multiple` lets several stay open.
// `value` with `onValueChange` (or `defaultValue` alone) is the open row's value, or the list of them with `multiple`.
// Compose with AccordionItem.
export type AccordionValue = string | string[] | null
export interface AccordionProps {
  /** Several rows stay open. */
  multiple?: boolean
  /** The open row's value, or the list of them with `multiple`. */
  value?: AccordionValue
  defaultValue?: AccordionValue
  onValueChange?: (value: AccordionValue) => void
  className?: string
  children?: ReactNode
}

export function Accordion({ multiple, value, defaultValue = null, onValueChange, className, children }: AccordionProps) {
  const [model, setModel] = useControllable<AccordionValue>(value, defaultValue, onValueChange)
  const list = Array.isArray(model) ? model : model ? [model] : []
  const ctx = {
    isOpen: (v: string) => list.includes(v),
    toggle: (v: string) => {
      if (multiple) setModel(list.includes(v) ? list.filter(x => x !== v) : [...list, v])
      else setModel(list.includes(v) ? null : v)
    },
  }
  return (
    <AccordionContext.Provider value={ctx}>
      <div data-ds="accordion" className={cn('border-t border-edge', className)}>{children}</div>
    </AccordionContext.Provider>
  )
}

export default Accordion

'use client'
import { useId, type ReactNode } from 'react'
import { ChevronDown } from 'lucide-react'
import { useAccordion } from '@/react/hooks/useAccordion'

// One row of an Accordion: the question as a full-width button (ABC Diatype 16px, soft white that turns full white under
// the pointer and while open) over a neutral hairline, and the answer under it in dim (#B6B6B6) ABC Diatype 16/24, no wider than 640px (the site's FAQ: rows 56px tall, 20px in). The chevron turns
// half a circle as the row opens (320ms, ease-in-out); it never moves on hover. The closed answer is inert, so its
// links leave the tab order. `title` names the row; children are the answer.
export interface AccordionItemProps {
  /** The value the accordion opens it by. */
  value: string
  /** The question. */
  title?: ReactNode
  disabled?: boolean
  children?: ReactNode
}

export function AccordionItem({ value, title, disabled, children }: AccordionItemProps) {
  const ctx = useAccordion()
  const open = ctx?.isOpen(value) ?? false
  const id = useId()
  return (
    <>
      <style href="ds-accordion-item" precedence="ds">{css}</style>
      <div data-ds="accordion-item" className="border-b border-edge" data-open={open}>
        <h3>
          <button
            id={`${id}-head`}
            type="button"
            aria-expanded={open}
            aria-controls={`${id}-body`}
            disabled={disabled}
            className="flex min-h-control-lg w-full cursor-pointer items-center justify-between gap-6 py-5 text-left type-body text-fg-soft transition-[color] duration-150 ease-standard hover:text-fg aria-expanded:text-fg disabled:cursor-not-allowed disabled:text-fg-faint"
            onClick={() => ctx?.toggle(value)}
          >
            {title}
            <ChevronDown size={16} strokeWidth={1.5} aria-hidden="true" className="ds-accordion-chev shrink-0 text-fg-muted" />
          </button>
        </h3>
        <div id={`${id}-body`} role="region" aria-labelledby={`${id}-head`} inert={!open} className="ds-collapse" data-open={open}>
          <div><div className="ds-collapse-body max-w-measure pb-6 type-body text-fg-soft">{children}</div></div>
        </div>
      </div>
    </>
  )
}

export default AccordionItem

