import { html, type PropertyValues } from 'lit'
import { DsElement, define, HostLayoutController, tagName } from '@/elements/lib/element'
import styles from 'virtual:tw'

// Accordion.tsx as <agd-accordion>: a stack of disclosures on black with neutral hairlines between the rows, a
// muted chevron that turns as a row opens, the row opening to its content's height over 320ms on the strong ease-out
// and closing in 160ms. One open at a time by default (a second press closes it); `multiple` lets several stay open.
// `value` is the open row's value (or a JSON list of them with `multiple`), with `input` and `change` events. Compose
// with <agd-accordion-item>.
export type AccordionValue = string | string[] | null

/**
 * @summary A stack of disclosures, one open at a time or several.
 * @slot - The rows: <agd-accordion-item>.
 * @fires input - A row opened or closed (read `value`).
 * @fires change - A row opened or closed (read `value`).
 */
export class Accordion extends DsElement {
	static styles = [DsElement.styles, styles]
	// Layout classes on the element (w-full, max-w-160) land on the stack, as on the React root.
	protected readonly layout = new HostLayoutController(this, () => this.renderRoot.querySelector<HTMLElement>('[data-ds="accordion"]'))
	static properties = {
		multiple: { type: Boolean },
		value: { converter: { fromAttribute: (v: string | null) => (v?.trim().startsWith('[') ? JSON.parse(v) : v || null), toAttribute: (v: AccordionValue) => (Array.isArray(v) ? JSON.stringify(v) : v) } },
	}

	/** Several rows stay open. */
	multiple = false
	/** The open row's value, or the list of them with `multiple`. */
	value: AccordionValue = null

	private list() {
		return Array.isArray(this.value) ? this.value : this.value ? [this.value] : []
	}
	/** Whether the row with this value is open (read by the items). */
	isOpen(v: string) {
		return this.list().includes(v)
	}
	/** Opens or closes the row with this value (the items' press). */
	toggle(v: string) {
		const open = this.list()
		if (this.multiple) this.commit(open.includes(v) ? open.filter((x) => x !== v) : [...open, v])
		else this.commit(open.includes(v) ? null : v)
	}

	protected updated(changed: PropertyValues<this>) {
		super.updated(changed)
		if (changed.has('value')) for (const item of this.querySelectorAll<HTMLElement & { requestUpdate(): void }>(tagName('accordion-item'))) item.requestUpdate()
	}

	render() {
		return html`<div data-ds="accordion" class="border-t border-edge"><slot></slot></div>`
	}
}

define('accordion', Accordion)

import { html } from 'lit'
import { ChevronDown } from 'lucide'
import { accordionOf } from '@/elements/controllers/accordion'
import { DsElement, define, uid } from '@/elements/lib/element'
import { icon } from '@/elements/lib/icon'
import styles from 'virtual:tw'

// AccordionItem.tsx as <agd-accordion-item>: one row of an accordion: the question as a full-width button (ABC Diatype
// 16px, soft white that turns full white under the pointer and while open) over a neutral hairline, and the answer
// under it in muted ABC Diatype 14px. The chevron turns half a circle as the row opens; it never moves on hover. The closed
// answer is inert, so its links leave the tab order. `heading` (React's `title`) or the `title` slot names the row; the
// default slot is the answer.

/**
 * @summary One row of an accordion.
 * @slot - The answer.
 * @slot title - The question, in place of `heading`.
 */
export class AccordionItem extends DsElement {
	static styles = [DsElement.styles, styles]
	static properties = { value: {}, heading: {}, disabled: { type: Boolean } }

	/** The value the accordion opens it by. */
	value = ''
	/** The question (React's `title`). */
	heading?: string
	disabled = false
	private rowId = uid('accordion')

	render() {
		const ctx = accordionOf(this)
		const open = ctx?.isOpen(this.value) ?? false
		return html`<div data-ds="accordion-item" class="border-b border-edge" data-open=${String(open)}>
			<h3>
				<button id=${`${this.rowId}-head`} type="button" aria-expanded=${String(open)} aria-controls=${`${this.rowId}-body`} ?disabled=${this.disabled} class="flex min-h-control-lg w-full cursor-pointer items-center justify-between gap-6 py-5 text-left type-body text-fg-soft transition-[color] duration-150 ease-standard hover:text-fg aria-expanded:text-fg disabled:cursor-not-allowed disabled:text-fg-faint" @click=${() => ctx?.toggle(this.value)}><slot name="title">${this.heading}</slot>${icon(ChevronDown, 'chevron-down', { size: 16, strokeWidth: 1.5, class: 'ds-accordion-chev shrink-0 text-fg-muted', attrs: { 'aria-hidden': 'true' } })}</button>
			</h3>
			<div id=${`${this.rowId}-body`} role="region" aria-labelledby=${`${this.rowId}-head`} ?inert=${!open} class="ds-collapse" data-open=${String(open)}>
				<div><div class="ds-collapse-body max-w-measure pb-6 type-body text-fg-soft"><slot></slot></div></div>
			</div>
		</div>`
	}
}

define('accordion-item', AccordionItem)

/* AccordionItem.tsx's styles, as they are. */
/* The row opens to its content's height (0fr to 1fr) over 320ms and closes in 160ms, on the strong ease-out; the words
   fade and settle 4px down, so they never pop. Reduced motion: no height or move, opacity only. */
.ds-collapse { display: grid; grid-template-rows: 0fr; transition: grid-template-rows var(--ds-duration-exit) var(--ds-easing-out); }
.ds-collapse[data-open="true"] { grid-template-rows: 1fr; transition-duration: var(--ds-duration-glide); }
.ds-collapse > div { min-height: 0; overflow: hidden; }
.ds-collapse-body { opacity: 0; transform: translateY(-4px); transition: opacity var(--ds-duration-exit) var(--ds-easing-standard), transform var(--ds-duration-exit) var(--ds-easing-out); }
.ds-collapse[data-open="true"] .ds-collapse-body { opacity: 1; transform: none; transition-duration: var(--ds-duration-glide); }
.ds-accordion-chev { transition: rotate var(--ds-duration-glide) var(--ds-easing-in-out); }
[aria-expanded="true"] > .ds-accordion-chev { rotate: 180deg; }
@media (prefers-reduced-motion: reduce) {
  .ds-collapse, .ds-collapse[data-open="true"], .ds-accordion-chev { transition: none; }
  .ds-collapse-body, .ds-collapse[data-open="true"] .ds-collapse-body { transform: none; transition: opacity var(--ds-duration-micro) var(--ds-easing-standard); }
}

import { tagName } from '@/elements/lib/element'

// useAccordion for elements: what a <agd-accordion> gives its items (whether a value is open, and the press that
// opens or closes it). An item finds its accordion as its closest ancestor, so accordions nest.
export type AccordionContext = { isOpen: (v: string) => boolean, toggle: (v: string) => void }

/** The accordion around an item, or null outside one (or while it is not defined yet: it renders its items again once
 * it is). */
export function accordionOf(item: Element): AccordionContext | null {
	const a = item.parentElement?.closest(tagName('accordion')) as (Element & Partial<AccordionContext>) | null
	return a && typeof a.isOpen === 'function' ? (a as AccordionContext) : null
}
